from contextlib import closing
from pathlib import Path
import sqlite3
import tempfile
import vault


def snapshot(path):
    with closing(sqlite3.connect(path)) as con:
        return {name: con.execute('SELECT * FROM ' + name + ' ORDER BY 1,2').fetchall()
                for name in ('accounts', 'transfers', 'audit')}


def native(path):
    with closing(sqlite3.connect(path)) as con, con:
        con.execute('BEGIN IMMEDIATE')
        con.execute(\"UPDATE accounts SET balance=90 WHERE tenant='one' AND name='a'\")
        con.execute(\"UPDATE accounts SET balance=10 WHERE tenant='one' AND name='b'\")
        for table in ('transfers', 'audit'):
            con.execute('INSERT INTO ' + table + ' VALUES (?,?,?,?,?)', ('one','k','a','b',10))
    return {'tenant':'one','key':'k','source':'a','target':'b','amount':10}

with tempfile.TemporaryDirectory(dir=Path.cwd(), prefix='assessment-') as tmp:
    root = Path(tmp)
    for case in ('trigger_order', 'rowid_view'):
        base = root / (case + '.sqlite')
        vault.init_db(base)
        with closing(sqlite3.connect(base)) as con, con:
            con.executescript(\"INSERT INTO accounts VALUES ('one','b',0),('one','a',100);\")
            if case == 'trigger_order':
                con.executescript(\"\"\"
                CREATE TRIGGER z_failure AFTER INSERT ON audit BEGIN
                    SELECT RAISE(ABORT, 'z_failure fired');
                END;
                CREATE TRIGGER a_skip AFTER INSERT ON audit BEGIN
                    SELECT RAISE(IGNORE);
                END;
                \"\"\")
            else:
                con.executescript(\"\"\"
                CREATE VIEW chosen_account AS SELECT name FROM accounts WHERE rowid=2;
                CREATE TRIGGER view_check BEFORE INSERT ON audit BEGIN
                    SELECT CASE WHEN (SELECT name FROM chosen_account) "'!= '"'a'
                        THEN RAISE(ABORT, 'view changed') END;
                END;
                \"\"\")
        for mode in ('native', 'candidate'):
            path = root / (case + '-' + mode + '.sqlite')
            with closing(sqlite3.connect(base)) as source, closing(sqlite3.connect(path)) as target:
                source.backup(target)
            before = snapshot(path)
            try:
                receipt = native(path) if mode == 'native' else vault.transfer(path, 'one','a','b',10,'k')
                result = ('success', receipt)
            except Exception as exc:
                result = (type(exc).__name__, str(exc))
            after = snapshot(path)
            print(case, mode, result, 'unchanged=', before == after, 'state=', after)
