        try:
            outcome = ('success', vault.transfer(path,'one','a','b',10,'k'))
        except Exception as exc:
            outcome = (type(exc).__name__, str(exc))
        print('identifier-case', 'hidden=', hidden, outcome, 'unchanged=', state(path) == before)
